const money = n => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(n || 0);
const dayKey = date => new Date(date).toLocaleDateString('en-CA');
let state = { products: seed, sales: [], purchases:[], stockMoves:[], archives: [], expenses: [], cash: [], cart: [], view: 'venta', query: '', category: 'Todos', restockQuery:'', folder: null, camera: null, stream: null, weightProduct: null, addOrigin:null, portionProduct:null, portionAmount:'', weightUnit:'g', weightAmount:'', dialog:null, operator:null, pinHash:null, folderAccess:'unknown', pendingOpening:null,inventoryFilter:'all',storagePersisted:null,storageUsage:null,storageQuota:null,folderSyncPending:false,dataLoaded:false };
let db;
const openDb = () => new Promise((resolve, reject) => {
  const request = indexedDB.open('tiendita-config', 1);
  request.onupgradeneeded = () => request.result.createObjectStore('settings');
  request.onsuccess = () => { db = request.result; resolve(db); }; request.onerror = () => reject(request.error);
});
const getHandle = () => new Promise(resolve => { const r=db.transaction('settings').objectStore('settings').get('folder');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null); });
const putHandle = handle => new Promise((resolve,reject)=>{const r=db.transaction('settings','readwrite').objectStore('settings').put(handle,'folder');r.onsuccess=resolve;r.onerror=()=>reject(r.error);});
const getSetting = key => new Promise(resolve=>{const r=db.transaction('settings').objectStore('settings').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);});
const putSetting = (key,value) => new Promise((resolve,reject)=>{const r=db.transaction('settings','readwrite').objectStore('settings').put(value,key);r.onsuccess=resolve;r.onerror=()=>reject(r.error);});
async function inspectStorage(){try{const storage=navigator.storage;if(!storage)return;state.storagePersisted=await storage.persisted?.()||false;if(!state.storagePersisted&&storage.persist)state.storagePersisted=await storage.persist().catch(()=>false);const estimate=await storage.estimate();state.storageUsage=Number(estimate.usage||0);state.storageQuota=Number(estimate.quota||0);}catch{}}function formatBytes(bytes){if(!Number.isFinite(bytes)||bytes<0)return 'No disponible';if(bytes<1024)return bytes+' B';const units=['KB','MB','GB'];let value=bytes/1024,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++;}return value.toFixed(value>=10?0:1)+' '+units[index];}
async function pinDigest(pin){const bytes=new TextEncoder().encode(`tiendita-pin-v1:${pin}`);const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');}
function applyData(data) { state.dataLoaded=true;state.products=data.products||seed;state.sales=data.sales||[];state.purchases=data.purchases||[];state.stockMoves=data.stockMoves||[];state.archives=data.archives||[];state.expenses=data.expenses||[];state.cash=data.cash||[]; }
function exportData() { return { version:3,updatedAt:new Date().toISOString(),products:state.products,sales:state.sales,purchases:state.purchases,stockMoves:state.stockMoves,archives:state.archives,expenses:state.expenses,cash:state.cash }; }
async function loadFile(){if(!state.folder)return false;try{if(await state.folder.queryPermission({mode:'readwrite'})!=='granted')return false;const file=await state.folder.getFileHandle('tiendita-datos.json');const disk=JSON.parse(await(await file.getFile()).text());const local=await getSetting('snapshot');if(local&&Date.parse(local.updatedAt||0)>Date.parse(disk.updatedAt||0)){applyData(local);const writer=await file.createWritable();await writer.write(JSON.stringify(local,null,2));await writer.close();}else{applyData(disk);await putSetting('snapshot',disk);}state.folderSyncPending=false;return true;}catch{return false;}}async function persist(){const data=exportData();try{await putSetting('snapshot',data);}catch(error){alert('No se pudo guardar la información en este dispositivo. '+error.message);return false;}state.dataLoaded=true;if(!state.folder){state.folderSyncPending=false;return true;}if(state.folderAccess!=='granted'){state.folderAccess='prompt';state.folderSyncPending=true;return true;}try{const file=await state.folder.getFileHandle('tiendita-datos.json',{create:true});const writer=await file.createWritable();await writer.write(JSON.stringify(data,null,2));await writer.close();state.folderSyncPending=false;return true;}catch{state.folderAccess='prompt';state.folderSyncPending=true;return true;}}async function chooseFolder(){try{if(state.folder&&await state.folder.queryPermission({mode:'readwrite'})!=='granted'){state.folderAccess=await state.folder.requestPermission({mode:'readwrite'});if(state.folderAccess!=='granted')return alert('No se concedió acceso. Puedes intentarlo de nuevo desde Ajustes.');if(!await loadFile())await persist();render();return;}if(!window.showDirectoryPicker)return alert('Elige una carpeta desde Chrome actualizado en Android.');state.folder=await window.showDirectoryPicker({id:'tiendita',mode:'readwrite'});await putHandle(state.folder);if(navigator.storage?.persist)await navigator.storage.persist().catch(()=>false);state.folderAccess=await state.folder.queryPermission({mode:'readwrite'});if(state.folderAccess!=='granted')state.folderAccess=await state.folder.requestPermission({mode:'readwrite'});if(state.folderAccess==='granted'){if(!await loadFile())await persist();render();}else alert('No se concedió acceso a la carpeta. Puedes intentarlo de nuevo desde Ajustes.');}catch(e){if(e.name!=='AbortError')alert('No se pudo abrir la carpeta.');}}
async function login(){const form=document.querySelector('#login-form');const data=new FormData(form);const name=String(data.get('name')||'').trim();const pin=String(data.get('pin')||'');const opening=Number(data.get('opening')||0);if(!name||!pin)return alert('Escribe tu nombre y contraseña.');if(await pinDigest(pin)!==state.pinHash)return alert('La contraseña no es correcta.');if(state.folder&&state.folderAccess==='granted'&&!state.dataLoaded)await loadFile();if(state.folder&&!state.dataLoaded){state.operator=name;state.view='ajustes';render();return alert('Para abrir la información guardada, ve a Ajustes y pulsa “Reconectar carpeta”. No se solicitará acceso durante el login.');}state.pendingOpening=opening;const session=state.cash.find(c=>c.status==='open');if(session){state.operator=session.operator||(session.logins||[]).at(-1)?.name||name;state.pendingOpening=null;render();return;}state.operator=name;if(opening<0)return;const newSession={id:crypto.randomUUID(),openedAt:new Date().toISOString(),opening,status:'open',operator:name,logins:[{name,date:new Date().toISOString()}]};state.cash.push(newSession);state.pendingOpening=null;if(await persist())render();else state.operator=null;}
function logout(){if(isOpen())return alert('La sesión permanece activa hasta cerrar la caja.');state.operator=null;state.cart=[];render();}
function openProductForm(product=null){state.productReturnView=state.view;state.dialog={type:product?'product-edit':'product-new',product};render();}function openProductDelete(product){state.dialog={type:'delete-product',product};render();}async function confirmProductDelete(){const dialog=state.dialog;if(dialog?.type!=='delete-product'||dialog.deleting)return;dialog.deleting=true;document.querySelector('.delete-modal')?.classList.add('is-deleting');const button=document.querySelector('[data-action="confirm-delete-product"]');if(button){button.disabled=true;button.textContent='Eliminando…';}setTimeout(async()=>{const previousProducts=state.products,previousCart=state.cart;state.products=state.products.filter(p=>p.id!==dialog.product.id);state.cart=state.cart.filter(row=>row.id!==dialog.product.id);state.dialog=null;if(!await persist()){state.products=previousProducts;state.cart=previousCart;alert('No se pudo eliminar el producto. No se hicieron cambios.');}render();},480);}
function saveProduct(form){const d=new FormData(form),old=state.dialog.product,stock=old?old.stock:Number(d.get('stock')||0),now=new Date().toISOString();const product={id:old?.id||crypto.randomUUID(),name:String(d.get('name')).trim(),brand:String(d.get('brand')||'').trim(),detail:String(d.get('detail')||'').trim(),category:String(d.get('category')).trim(),image:String(d.get('image')),code:String(d.get('code')||'').trim(),unit:String(d.get('unit')),price:Number(d.get('price')),cost:Number(d.get('cost')),stock,minimum:Number(d.get('minimum')||0),content:String(d.get('content')||'').trim(),expiry:String(d.get('expiry')||''),soldSinceRestock:old?Number(old.soldSinceRestock||0):0,lastRestockAt:old?.lastRestockAt||null};if(old)state.products=state.products.map(p=>p.id===old.id?product:p);else{state.products.push(product);if(stock>0){product.lastRestockAt=now;state.purchases.push({id:crypto.randomUUID(),productId:product.id,productName:product.name,quantity:stock,unit:product.unit,unitCost:product.cost,total:stock*product.cost,supplier:String(d.get('supplier')||''),date:now,operator:state.operator,type:'initial'});state.stockMoves.push({id:crypto.randomUUID(),productId:product.id,type:'initial',quantity:stock,after:stock,date:now,operator:state.operator});}}state.view=state.productReturnView||'inventario';state.productReturnView=null;state.dialog=null;persist().then(render);}function openMovement(type,product){state.movementReturnView=state.view==='resurtir'?'reinversion':state.view;state.dialog={type,product};render();}
async function saveMovement(form){const data=new FormData(form),p=state.dialog.product,quantity=Number(data.get('quantity'));if(!(quantity>0))return alert('Escribe una cantidad mayor a cero.');if(state.dialog.type==='purchase'){const unitCost=Number(data.get('unitCost'));if(!(unitCost>=0))return alert('Revisa el costo de compra.');const previous=p.stock,combined=previous+quantity;p.cost=combined?((previous*p.cost)+(quantity*unitCost))/combined:unitCost;p.stock=combined;p.lastRestockAt=new Date().toISOString();p.soldSinceRestock=0;state.purchases.push({id:crypto.randomUUID(),productId:p.id,productName:p.name,quantity,unit:p.unit,unitCost,total:quantity*unitCost,supplier:String(data.get('supplier')||''),date:new Date().toISOString(),operator:state.operator});state.stockMoves.push({id:crypto.randomUUID(),productId:p.id,type:'purchase',quantity,after:p.stock,date:new Date().toISOString(),operator:state.operator});}else{const before=p.stock;p.stock=quantity;state.stockMoves.push({id:crypto.randomUUID(),productId:p.id,type:'count',before,quantity,delta:quantity-before,date:new Date().toISOString(),operator:state.operator});}state.dialog=null;if(state.movementReturnView){state.view=state.movementReturnView;state.movementReturnView=null;}if(await persist())render();}
async function changePin(form){const data=new FormData(form),current=String(data.get('current')),next=String(data.get('next'));if(await pinDigest(current)!==state.pinHash)return alert('La contraseña actual no coincide.');if(!/^\d{4,8}$/.test(next))return alert('El PIN nuevo debe tener de 4 a 8 números.');state.pinHash=await pinDigest(next);await putSetting('pinHash',state.pinHash);state.dialog=null;render();alert('Contraseña actualizada en este dispositivo.');}
const cats=()=>['Todos',...new Set(state.products.map(p=>p.category))];
function imageFor(p){if(p.image)return p.image;const name=`${p.name} ${p.brand||''} ${p.detail||''}`.toLowerCase();if(/coca|refresco|soda/.test(name))return 'soda';if(/agua|water/.test(name))return 'water';if(/leche/.test(name))return 'milk';if(/queso/.test(name))return 'cheese';if(/jam[oó]n|pavo/.test(name))return 'turkey-leg';if(/huevo|egg/.test(name))return 'eggs';return 'chips';}
