function captureCartOrigin(element){const img=element?.querySelector('.product-icon');if(!img)return null;const r=img.getBoundingClientRect();return{src:img.currentSrc||img.src,rect:{left:r.left,top:r.top,width:r.width,height:r.height}};}
function animateCartFly(origin){if(!origin?.src||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const dock=document.querySelector('.cart-dock'),target=dock&&getComputedStyle(dock).display!=='none'?dock:document.querySelector('.ticket-head');if(!target)return;const to=target.getBoundingClientRect(),from=origin.rect;if(!to.width||!to.height)return;const fly=document.createElement('img');fly.src=origin.src;fly.alt='';fly.setAttribute('aria-hidden','true');fly.className='cart-fly';const size=38;fly.style.left=(from.left+from.width/2-size/2)+'px';fly.style.top=(from.top+from.height/2-size/2)+'px';document.body.append(fly);const dx=to.left+to.width/2-(from.left+from.width/2),dy=to.top+to.height/2-(from.top+from.height/2);const motion=fly.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:'translate('+dx+'px,'+dy+'px) scale(.18)',opacity:.18}],{duration:560,easing:'cubic-bezier(.2,.75,.25,1)'});motion.onfinish=()=>fly.remove();}
function add(product,qty=1){const row=state.cart.find(x=>x.id===product.id),unit=product.unit==='docena'?'pieza':['kg','gramo'].includes(product.unit)?'kg':product.unit,price=product.unit==='gramo'?product.price*1000:product.unit==='docena'?product.price/12:product.price,cost=product.unit==='gramo'?product.cost*1000:product.unit==='docena'?product.cost/12:product.cost;if(row)row.qty=Math.round((row.qty+qty)*1000)/1000;else state.cart.push({id:product.id,name:product.name,unit,qty,price,cost});render();}
function portionModal(){const p=state.portionProduct,amount=Number(state.portionAmount||0),valid=Number.isInteger(amount)&&amount>0;return `<div class="modal-backdrop" data-action="dismiss-egg"><section class="weight-modal portion-modal" role="dialog" aria-modal="true" aria-labelledby="egg-title"><button class="modal-close" data-action="cancel-egg" aria-label="Cerrar">×</button><div class="weight-icon">🥚</div><span class="eyebrow">VENTA DE HUEVO</span><h2 id="egg-title">${escapeHtml(p.name)}</h2><p class="weight-hint">Precio por docena: <b>${money(p.price)}</b><span> · ${money(p.price/12)} por pieza</span></p><div class="portion-shortcuts"><button type="button" data-egg-quick="12"><b>Docena</b><small>12 piezas</small></button><button type="button" data-egg-quick="6"><b>Media docena</b><small>6 piezas</small></button><button type="button" data-egg-quick="3"><b>3 piezas</b><small>Cuarto de docena</small></button><button type="button" data-egg-quick="4"><b>4 piezas</b><small>Un tercio de docena</small></button></div><label for="egg-amount">O escribe otra cantidad de piezas</label><div class="weight-input-wrap"><input id="egg-amount" type="number" min="1" step="1" inputmode="numeric" placeholder="Ej. 3" value="${escapeHtml(state.portionAmount||'')}"><span>piezas</span></div><div class="weight-preview" id="egg-preview">${valid?`Total: ${money(p.price*amount/12)}`:'Elige una cantidad para calcular el total'}</div><button class="charge-btn" data-action="confirm-egg" ${valid?'':'disabled'}>Agregar a la cuenta <span>→</span></button></section></div>`;}
function weightModal(){const p=state.weightProduct,unit=state.weightUnit||'g',amount=Number(state.weightAmount||0),kg=unit==='g'?amount/1000:amount,valid=amount>0;return `<div class="modal-backdrop" data-action="dismiss-weight"><section class="weight-modal" role="dialog" aria-modal="true" aria-labelledby="weight-title"><button class="modal-close" data-action="cancel-weight" aria-label="Cerrar">×</button><div class="weight-icon">⚖️</div><span class="eyebrow">VENTA POR PESO</span><h2 id="weight-title">${escapeHtml(p.name)}</h2><p class="weight-hint">Precio por kilo: <b>${money(p.unit==='gramo'?p.price*1000:p.price)}</b></p><label>¿Qué cantidad pidió?</label><div class="weight-units"><button type="button" data-weight-unit="g" class="${unit==='g'?'selected':''}">Gramos</button><button type="button" data-weight-unit="kg" class="${unit==='kg'?'selected':''}">Kilos</button></div><div class="weight-input-wrap"><input id="weight-amount" type="number" min="${unit==='g'?'1':'0.001'}" step="${unit==='g'?'1':'0.001'}" inputmode="decimal" placeholder="${unit==='g'?'250':'0.25'}" value="${escapeHtml(state.weightAmount||'')}"><span>${unit==='g'?'gramos':'kilos'}</span></div><div class="weight-preview" id="weight-preview">${valid?`Total: ${money((p.unit==='gramo'?p.price*1000:p.price)*kg)}`:'Escribe la cantidad para calcular el total'}</div><button class="charge-btn" data-action="confirm-weight" ${valid?'':'disabled'}>Agregar a la cuenta <span>→</span></button></section></div>`;}function checkout(){if(!state.cart.length)return;if(!isOpen())return alert('Abre la caja antes de registrar ventas.');state.dialog={type:'payment',total:cartTotal(),method:'efectivo',paid:''};render();}
async function completePayment(form){const total=cartTotal(),method=state.dialog.method,paid=method==='efectivo'?Number(new FormData(form).get('paid')):total;if(method==='efectivo'&&(!Number.isFinite(paid)||paid<total))return alert('El monto recibido debe cubrir el total.');const sale={id:crypto.randomUUID(),date:new Date().toISOString(),total,paid,change:method==='efectivo'?Math.round((paid-total)*100)/100:0,method,operator:state.operator,items:structuredClone(state.cart)};for(const item of sale.items){const p=state.products.find(p=>p.id===item.id);if(p){const stockQty=p.unit==='gramo'?item.qty*1000:p.unit==='docena'?item.qty/12:item.qty;p.stock=Math.max(0,Math.round((p.stock-stockQty)*1000)/1000);p.soldSinceRestock=Number(p.soldSinceRestock||0)+stockQty;}}state.sales.push(sale);if(!await persist())return;state.cart=[];state.dialog=null;render();}
async function addProduct(){const name=prompt('Nombre del producto');if(!name)return;const price=Number(prompt('Precio de venta ($)'));if(!(price>0))return;const cost=Number(prompt('Costo de compra ($)'));if(!(cost>=0))return;const unit=prompt('Unidad: pieza, kg o docena','pieza')||'pieza';const code=prompt('Código de barras (opcional)','')||'';state.products.push({id:crypto.randomUUID(),name,code,category:prompt('Categoría','Abarrotes')||'Abarrotes',price,cost,stock:0,unit});await persist();render();}
async function openCash(){if(isOpen())return alert('La caja ya está abierta.');const opening=state.pendingOpening??Number(prompt('Efectivo inicial en caja ($)',''));state.pendingOpening=null;if(!Number.isFinite(opening)||opening<0)return;state.cash.push({id:crypto.randomUUID(),openedAt:new Date().toISOString(),opening,status:'open',operator:state.operator,logins:[{name:state.operator,date:new Date().toISOString()}]});if(await persist())render();}
async function closeCash(){const session=state.cash.find(c=>c.status==='open');if(!session)return;const sales=state.sales.filter(s=>s.date>=session.openedAt);const cashSales=sales.filter(s=>s.method==='efectivo').reduce((n,s)=>n+s.total,0);const nonCash=sales.filter(s=>s.method!=='efectivo').reduce((n,s)=>n+s.total,0);const cashIn=state.cash.filter(c=>c.type==='in'&&c.date>=session.openedAt).reduce((n,c)=>n+c.amount,0);const cashOutRows=state.cash.filter(c=>c.type==='out'&&c.date>=session.openedAt),cashOut=cashOutRows.reduce((n,c)=>n+c.amount,0);const expected=session.opening+cashSales+cashIn-cashOut;const productMap=new Map();for(const sale of sales)for(const item of sale.items){const row=productMap.get(item.id)||{name:item.name,unit:item.unit||'pieza',quantity:0,total:0};row.quantity+=item.qty;row.total+=item.qty*item.price;productMap.set(item.id,row);}state.dialog={type:'close-summary',session,sales,cashSales,nonCash,cashIn,cashOut,cashOutRows,expected,productRows:[...productMap.values()]};render();}
async function completeCashClose(form){const report=state.dialog;const counted=Number(new FormData(form).get('counted'));if(!Number.isFinite(counted)||counted<0)return alert('Escribe cuánto efectivo contaste.');const s=report.session;s.status='closed';s.closedAt=new Date().toISOString();s.expected=report.expected;s.counted=counted;s.difference=counted-report.expected;s.salesTotal=report.cashSales+report.nonCash;s.report={sales:report.sales.map(x=>({id:x.id,date:x.date,total:x.total,method:x.method,items:x.items})),products:report.productRows,cashSales:report.cashSales,nonCash:report.nonCash,cashIn:report.cashIn,cashOut:report.cashOut,cashOutRows:(report.cashOutRows||[]).map(x=>({amount:x.amount,reason:x.reason,note:x.note,date:x.date}))};if(await persist()){state.dialog=null;state.operator=null;state.cart=[];render();}else{s.status='open';delete s.closedAt;delete s.expected;delete s.counted;delete s.difference;delete s.salesTotal;delete s.report;state.dialog=report;state.operator=s.operator||null;render();}}async function cashMovement(type){if(type!=='out')return;state.dialog={type:'cash-out'};render();}
async function completeCashOut(form){const data=new FormData(form),amount=Number(data.get('amount'));if(!(amount>0))return alert('Escribe un monto mayor a cero.');state.cash.push({id:crypto.randomUUID(),type:'out',amount,reason:String(data.get('reason')||'otro'),note:String(data.get('note')||'').trim(),date:new Date().toISOString(),operator:state.operator,sessionId:state.cash.find(c=>c.status==='open')?.id||null});if(await persist()){state.dialog=null;render();}}
function backup(){const blob=new Blob([JSON.stringify(exportData(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`respaldo-tiendita-${today()}.json`;a.click();URL.revokeObjectURL(url);}
function restore(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const data=JSON.parse(await input.files[0].text());if(!Array.isArray(data.products)||!Array.isArray(data.sales))throw Error('Formato no válido');if(!confirm('Restaurar reemplazará los datos actuales. ¿Continuar?'))return;applyData(data);if(await persist())render();}catch(e){alert(`No se pudo restaurar el archivo: ${e.message}`);}};input.click();}
async function archiveOldSales(){const cutoff=new Date();cutoff.setFullYear(cutoff.getFullYear()-1);const old=state.sales.filter(s=>new Date(s.date)<cutoff);if(!old.length)return alert('No hay ventas con más de un año para archivar.');const grouped=new Map();for(const sale of old){const month=dayKey(sale.date).slice(0,7);const row=grouped.get(month)||{month,sales:0,revenue:0,cost:0,profit:0,count:0};row.sales+=sale.total;row.count++;for(const i of sale.items||[])row.cost+=i.cost*i.qty;row.profit=row.sales-row.cost;grouped.set(month,row);}const additions=[...grouped.values()];const msg=`Se resumirán ${old.length} ventas anteriores a ${cutoff.toLocaleDateString('es-MX')} y se eliminará su detalle. Se conservarán ingresos, costo, utilidad y cantidad por mes.\n\nDescarga un respaldo antes de continuar. ¿Archivar?`;if(!confirm(msg))return;backup();state.archives.push(...additions);state.sales=state.sales.filter(s=>new Date(s.date)>=cutoff);if(await persist()){render();alert('Historial archivado; los totales mensuales se conservaron.');}}
function stopCamera(){state.stream?.getTracks().forEach(t=>t.stop());state.stream=null;state.camera=null;}
async function startCamera(){if(!('BarcodeDetector'in window))return alert('Este navegador no incluye lector de códigos. Prueba con Chrome actualizado en Android o usa la pistola escáner.');try{const formats=await BarcodeDetector.getSupportedFormats();const detector=new BarcodeDetector({formats});state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false});state.view='venta';state.camera={detector,formats};render();const video=document.querySelector('#camera-video');video.srcObject=state.stream;await video.play();const scan=async()=>{if(!state.camera)return;try{const codes=await detector.detect(video);if(codes.length){const code=codes[0].rawValue;stopCamera();state.query=code;const p=state.products.find(p=>p.code===code);render();if(p)add(p);else alert(`Código ${code}: producto no registrado. Agrégalo desde Inventario.`);return;}}catch{}requestAnimationFrame(scan);};requestAnimationFrame(scan);}catch(e){stopCamera();alert(`No se pudo abrir la cámara. Revisa el permiso del navegador. ${e.message}`);}}
function cartDock(){return `<button class="cart-dock ${state.cart.length?'shown':''}" data-action="view-cart" ${state.cart.length?'':'disabled'} aria-label="Ver cuenta, ${money(cartTotal())}"><span class="cart-dock-icon">🧺<i>${state.cart.length}</i></span><span class="cart-dock-copy"><b>Cuenta</b><small>${state.cart.length} ${state.cart.length===1?'artículo':'artículos'}</small></span><strong>${money(cartTotal())} <span>Ver →</span></strong></button>`;}
function layout(){const title={venta:'Punto de venta',inventario:'Inventario',resumen:'Resumen',reinversion:'Reinversión',resurtir:'Resurtir producto',ajustes:'Ajustes'}[state.view];return `<div class="shell"><aside class="rail"><div class="brand"><span class="brand-mark">L</span><span>la tiendita<small>punto de venta</small></span></div><nav>${nav('venta','▦','Vender')}${nav('inventario','▤','Inventario')}${nav('resumen','◷','Resumen')}${nav('reinversion','↗','Reinversión')}${nav('ajustes','⚙','Ajustes')}</nav><div class="rail-foot"><span class="status-dot ${state.folderAccess==='granted'?'online':''}"></span>${state.folderAccess==='granted'?'Carpeta conectada':state.folder?'Carpeta guardada · reconectar':'Guardado local · sin carpeta'}</div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">TU NEGOCIO, EN ORDEN</div><h1>${title}</h1></div>${state.view==='venta'?`<button class="cash-pill ${isOpen()?'open':''}" data-action="cash" aria-label="${isOpen()?'Hacer corte y cerrar la caja':'Abrir caja'}">${isOpen()?`<span class="cash-pill-dot"></span><span>Caja abierta</span><small>Corte →</small>`:'＋ Abrir caja'}</button>`:''}</header>${state.camera?`<section class="camera-card"><div class="section-head"><h2>Escanea el código</h2><button class="text-button" data-action="stop-camera">Cerrar cámara</button></div><video id="camera-video" playsinline></video><p>Centra el código de barras. Mantén la etiqueta enfocada y evita reflejos.</p><small>Formatos disponibles: ${state.camera.formats.join(', ')}</small></section>`:state.view==='venta'?salesPage():state.view==='inventario'?inventoryPage():state.view==='resumen'?summaryPage():state.view==='reinversion'?reinvestmentPage():state.view==='resurtir'?restockSelectionPage():settingsPage()}</main>${state.view==='venta'?cartDock():''}<nav class="mobile-nav">${nav('venta','▦','Vender')}${nav('inventario','▤','Stock')}${nav('resumen','◷','Resumen')}${nav('reinversion','↗','Reinversión')}${nav('ajustes','⚙','Ajustes')}</nav>${state.weightProduct?weightModal():''}${state.portionProduct?portionModal():''}${state.dialog?dialogView():''}</div>`;}function nav(id,icon,label){return `<button class="nav-item ${(state.view===id||(id==='reinversion'&&state.view==='resurtir'))?'active':''}" data-view="${id}"><span>${icon}</span><b>${label}</b></button>`;}
function salesPage(){return `<div class="page-grid"><section class="catalog"><div class="search-wrap"><span>⌕</span><input id="search" value="${escapeHtml(state.query)}" placeholder="Busca o escanea un producto" autocomplete="off"><button class="camera-btn" data-action="camera">▣ Cámara</button><kbd>PISTOLA</kbd></div><div class="chips">${cats().map(c=>`<button class="chip ${state.category===c?'selected':''}" data-cat="${escapeHtml(c)}">${escapeHtml(c)}</button>`).join('')}</div><div class="product-grid">${filtered().map(p=>`<button class="product-card" data-add="${p.id}"><img class="product-icon" src="./assets/products/${imageFor(p)}.svg" alt=""><span class="product-cart-indicator" data-cart-indicator="${p.id}" hidden></span><div class="product-name">${escapeHtml(p.name)}</div><div class="product-meta">${escapeHtml(p.detail||`${p.stock} ${p.unit} disponibles`)}</div><strong>${money(p.unit==='gramo'?p.price*1000:p.price)}<small>${['kg','gramo'].includes(p.unit)?' / kg':p.unit==='docena'?' / docena':''}</small></strong></button>`).join('')}</div></section><aside class="ticket"><div class="ticket-head"><div><span class="eyebrow">VENTA ACTUAL</span><h2>Cuenta</h2></div><button class="text-button" data-action="clear">Vaciar</button></div>${state.cart.length?`<div class="ticket-items">${state.cart.map(row=>`<div class="ticket-row"><div><b>${escapeHtml(row.name)}</b><small>${money(row.price)}${row.unit==='kg'?' / kg':row.unit==='pieza'?' / pieza':''}</small></div><div class="qty"><button data-qty="${row.id}" data-delta="-1">−</button><input data-inputqty="${row.id}" value="${row.qty}"><button data-qty="${row.id}" data-delta="1">+</button><span class="qty-unit">${escapeHtml(row.unit)}</span></div><strong>${money(row.qty*row.price)}</strong></div>`).join('')}</div>`:`<div class="empty-ticket"><span>🧺</span><b>Tu cuenta está vacía</b><small>Toca un producto o escanéalo para comenzar.</small></div>`}<div class="ticket-bottom"><div class="total-line"><span>Total</span><strong>${money(cartTotal())}</strong></div><button class="charge-btn" data-action="charge" ${state.cart.length?'':'disabled'}>Cobrar <span>→</span></button><div class="secure-note">${state.folderAccess==='granted' ? '▣ Guardado en este teléfono y sincronizado con la carpeta' : state.folder ? '▣ Guardado en este teléfono · falta sincronizar la carpeta; reconecta desde Ajustes' : '▣ Guardado en este teléfono · puedes conectar una carpeta para otra copia'}</div></div></aside></div>`;}function daysUntilExpiry(date){if(!date)return null;const target=new Date(date+'T00:00:00'),today=new Date();today.setHours(0,0,0,0);return Math.floor((target-today)/86400000);}function expiryLabel(date){const days=daysUntilExpiry(date);if(days<0)return 'Caducó hace '+Math.abs(days)+' días';if(days===0)return 'Caduca hoy';if(days===1)return 'Caduca mañana';if(days<=7)return 'En '+days+' días';return new Date(date+'T00:00:00').toLocaleDateString('es-MX',{day:'numeric',month:'short'});}const inventoryCounts=()=>({all:state.products.length,low:state.products.filter(p=>Number(p.stock)<Number(p.minimum||0)).length,expiry:state.products.filter(p=>p.expiry&&daysUntilExpiry(p.expiry)<=7).length});const inventoryProducts=()=>state.products.filter(p=>state.inventoryFilter==='all'||(state.inventoryFilter==='low'?Number(p.stock)<Number(p.minimum||0):p.expiry&&daysUntilExpiry(p.expiry)<=7));
function inventoryPage(){return `<section class="inventory-panel"><div class="section-head"><div><span class="eyebrow">FICHAS Y EXISTENCIAS</span><h2>Inventario</h2></div><button class="primary-btn" data-action="new-product">＋ Nuevo producto</button></div><div class="inventory-filters"><button class="${state.inventoryFilter==='all'?'selected':''}" data-inventory-filter="all">Todos <b>${inventoryCounts().all}</b></button><button class="${state.inventoryFilter==='low'?'selected':''}" data-inventory-filter="low">Por reponer <b>${inventoryCounts().low}</b></button><button class="${state.inventoryFilter==='expiry'?'selected':''}" data-inventory-filter="expiry">Caducidad próxima <b>${inventoryCounts().expiry}</b></button></div><div class="inventory-cards">${inventoryProducts().map(p=>`<article class="inventory-card"><img class="inventory-art" src="./assets/products/${imageFor(p)}.svg" alt="Ilustración de ${escapeHtml(p.name)}"><div class="inventory-info"><div class="inventory-title"><div><span class="eyebrow">${escapeHtml(p.category)}</span><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml([p.brand,p.detail,p.content].filter(Boolean).join(' · '))}</p></div><div class="inventory-title-actions"><button class="icon-edit" data-edit="${p.id}" aria-label="Editar ${escapeHtml(p.name)}" title="Editar producto">✎</button><button class="icon-delete" data-delete-product="${p.id}" aria-label="Eliminar ${escapeHtml(p.name)}" title="Eliminar producto"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/></svg></button></div></div><div class="product-specs"><span>Venta: <b>${money(p.price)} / ${escapeHtml(p.unit)}</b></span><span>Costo: <b>${money(p.cost)} / ${escapeHtml(p.unit)}</b></span>${p.code?`<span>Código: <b>${escapeHtml(p.code)}</b></span>`:''}${p.expiry?`<span class="${daysUntilExpiry(p.expiry)<=7?'expiry-warning':''}">Caduca: <b>${expiryLabel(p.expiry)}</b></span>`:''}</div><div class="stock-line"><div><small>Existencia actual</small><b class="${p.stock<Number(p.minimum||0)?'stock-alert':''}">${p.stock} ${escapeHtml(p.unit)}${p.stock<Number(p.minimum||0)?' · Reponer pronto':''}</b></div><div class="stock-actions"><button class="secondary-btn" data-purchase="${p.id}">＋ Registrar compra</button><button class="secondary-btn" data-count="${p.id}">Contar</button></div></div></div></article>`).join('')}</div></section>`;}
function summaryPage(){const session=state.cash.find(c=>c.status==='open'),sales=session?state.sales.filter(s=>s.date>=session.openedAt):todaySales(),revenue=sales.reduce((n,s)=>n+s.total,0),profit=sales.reduce((n,s)=>n+s.items.reduce((m,i)=>m+(i.price-i.cost)*i.qty,0),0),cashSales=sales.filter(s=>s.method==='efectivo').reduce((n,s)=>n+s.total,0),nonCash=sales.filter(s=>s.method!=='efectivo').reduce((n,s)=>n+s.total,0),cashIn=state.cash.filter(c=>c.type==='in'&&(!session||c.date>=session.openedAt)).reduce((n,c)=>n+c.amount,0),cashOut=state.cash.filter(c=>c.type==='out'&&(!session||c.date>=session.openedAt)).reduce((n,c)=>n+c.amount,0),expected=session?session.opening+cashSales+cashIn-cashOut:0;return `<section class="summary"><span class="eyebrow">${session?'TURNO ACTUAL':'HOY'} · ${new Date().toLocaleDateString('es-MX',{weekday:'long',day:'numeric',month:'long'})}</span><h2>Así va tu tienda</h2><section class="cash-breakdown"><header><div><span class="eyebrow">CONTROL DE EFECTIVO</span><h3>${session?'Dinero en caja':'Caja cerrada'}</h3></div>${session?'<span class="cash-live"><i></i>Turno abierto</span>':''}</header><div class="cash-ledger-row"><div><b>Fondo inicial</b><small>Dinero con que abrió la caja</small></div><strong>${session?money(session.opening):'—'}</strong></div><div class="cash-ledger-row"><div><b>Ventas en efectivo</b><small>Dinero recibido en efectivo</small></div><strong class="cash-positive">+ ${money(cashSales)}</strong></div><div class="cash-ledger-row"><div><b>Tarjeta y transferencia</b><small>No se suman al efectivo del cajón</small></div><strong>${money(nonCash)}</strong></div>${cashIn?`<div class="cash-ledger-row"><div><b>Entradas registradas</b><small>Movimientos anteriores</small></div><strong class="cash-positive">+ ${money(cashIn)}</strong></div>`:''}<div class="cash-ledger-row"><div><b>Retiros y pagos</b><small>Salidas registradas en el turno</small></div><strong class="cash-negative">− ${money(cashOut)}</strong></div><div class="cash-ledger-total"><span>Efectivo esperado en caja</span><strong>${session?money(expected):'—'}</strong></div></section><div class="stat-grid summary-stat-grid"><article class="stat-card"><span>Ventas totales del turno</span><strong>${money(revenue)}</strong><small>${sales.length} ventas · cualquier forma de pago</small></article><article class="stat-card"><span>Ganancia bruta estimada</span><strong>${money(profit)}</strong><small>Ventas menos costo de los productos vendidos</small></article></div><div class="cash-actions">${isOpen()?'<button class="secondary-btn" data-action="cash-out">− Registrar salida de caja</button>':'<button class="primary-btn" data-action="cash">Abrir caja</button>'}</div><div class="inventory-panel recent"><div class="section-head"><div><span class="eyebrow">REGISTRO</span><h2>Ventas recientes</h2></div></div>${sales.length?sales.slice().reverse().slice(0,8).map(s=>`<div class="recent-row"><span>${new Date(s.date).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})} · ${s.method} · ${s.items.length} productos</span><b>${money(s.total)}</b></div>`).join(''):'<p class="muted">Todavía no hay ventas en este turno.</p>'}</div></section>`;}
function loginPage(){return `<main class="login-screen"><section class="login-card"><div class="brand-mark login-mark">L</div><span class="eyebrow">CONTROL DE CAJA</span><h1>Bienvenido a tu tienda</h1><p>Identifícate para abrir el turno.</p><form id="login-form"><label>Nombre de quien abre<input name="name" autocomplete="name" placeholder="Ej. Ana" required></label><label>Fondo inicial de caja<input name="opening" inputmode="decimal" type="number" min="0" step="0.01" placeholder="Ej. 1200" required></label><label>Contraseña<input name="pin" inputmode="numeric" type="password" placeholder="PIN de 4 números" required></label><button class="charge-btn" type="submit">Entrar <span>→</span></button></form><small>PIN inicial de demostración: 1234</small></section></main>`;}function paymentDialog(){const d=state.dialog,total=d.total,paid=Number(d.paid||0),cash=d.method==='efectivo',valid=!cash||paid>=total;return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal payment-modal" id="dialog-form" role="dialog" aria-modal="true" aria-labelledby="payment-title"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">FINALIZAR VENTA</span><h2 id="payment-title">¿Cómo va a pagar?</h2><div class="payment-total"><span>Total a cobrar</span><strong>${money(total)}</strong></div><div class="payment-methods"><button type="button" class="payment-option ${cash?'selected':''}" data-payment-method="efectivo"><span>💵</span><b>Efectivo</b></button><button type="button" class="payment-option ${!cash?'selected':''}" data-payment-method="tarjeta"><span>💳</span><b>Tarjeta</b></button></div>${cash?`<label class="payment-received">¿Cuánto pagó el cliente?<div class="money-input"><span>$</span><input id="payment-received" name="paid" type="number" min="${total}" step="0.01" inputmode="decimal" placeholder="Escribe el monto" value="${escapeHtml(d.paid||'')}" required></div></label><div class="payment-change"><span>Cambio</span><strong id="payment-change">${money(Math.max(0,paid-total))}</strong></div>`:`<div class="card-payment-note"><span>✓</span><p>Se registrará el cobro con tarjeta por <b>${money(total)}</b>.</p></div>`}<div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Volver</button><button class="primary-btn" type="submit" ${valid?'':'disabled'}>Confirmar cobro</button></div></form></div>`;}function deleteProductDialog(){const p=state.dialog.product,inCart=state.cart.some(row=>row.id===p.id);return `<div class="modal-backdrop" data-action="close-dialog"><section class="form-modal delete-modal" role="dialog" aria-modal="true" aria-labelledby="delete-product-title"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">INVENTARIO</span><div class="delete-product-visual"><img class="delete-product-art" src="./assets/products/${imageFor(p)}.svg" alt=""><span class="delete-bin" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/></svg></span></div><h2 id="delete-product-title">¿Eliminar “${escapeHtml(p.name)}”?</h2><p>Ya no aparecerá en el inventario ni en futuras ventas. El historial de ventas y cortes anteriores se conservará.${inCart?' También se quitará de la cuenta actual.':''}</p><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Conservar</button><button type="button" class="danger-btn" data-action="confirm-delete-product">Eliminar producto</button></div></section></div>`;}
function cashOutDialog(){return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">CONTROL DE CAJA</span><h2>Registrar salida de caja</h2><p>Indica a dónde va el dinero para que el corte muestre el efectivo restante.</p><label>¿Para qué sale el dinero?<select name="reason" required><option value="proveedor">Pagar a un proveedor</option><option value="resguardo">Guardar o depositar</option><option value="otro">Otro retiro</option></select></label><label>Monto que salió ($)<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="Ej. 350" required></label><label>Detalle o proveedor (opcional)<input name="note" placeholder="Ej. Pago a Bimbo"></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn" type="submit">Registrar salida</button></div></form></div>`;}
function dialogView(){const d=state.dialog;if(d.type==='delete-product')return deleteProductDialog();if(d.type==='close-summary')return closeCashDialog();if(d.type==='cash-out')return cashOutDialog();if(d.type==='payment')return paymentDialog();const p=d.product||{},titles={'product-new':'Nuevo producto','product-edit':'Editar producto',purchase:'Registrar compra',count:'Contar existencias',pin:'Cambiar contraseña'};if(d.type==='purchase'||d.type==='count')return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">${d.type==='purchase'?'ENTRADA DE MERCANCÍA':'CONTEO FÍSICO'}</span><h2>${titles[d.type]}</h2><p>${escapeHtml(p.name)} · ${escapeHtml(p.detail||p.unit)}</p><label>${d.type==='purchase'?'Cantidad que llegó':'Existencia encontrada'} (${escapeHtml(p.unit)})<input name="quantity" type="number" min="0.001" step="0.001" required autofocus></label>${d.type==='purchase'?`<label>Costo por ${escapeHtml(p.unit)} ($)<input name="unitCost" type="number" min="0" step="0.01" value="${p.cost||0}" required></label><label>Proveedor (opcional)<input name="supplier" placeholder="Nombre del proveedor"></label>`:''}<div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn" type="submit">${d.type==='purchase'?'Guardar compra':'Guardar conteo'}</button></div></form></div>`;if(d.type==='pin')return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">SEGURIDAD</span><h2>Cambiar contraseña</h2><label>Contraseña actual<input name="current" type="password" inputmode="numeric" required></label><label>Nueva contraseña (4 a 8 números)<input name="next" type="password" inputmode="numeric" minlength="4" maxlength="8" required></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn">Guardar contraseña</button></div></form></div>`;const editing=d.type==='product-edit';return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal product-form" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">FICHA DE PRODUCTO</span><h2>${titles[d.type]}</h2><div class="form-grid"><label>Nombre<input name="name" value="${escapeHtml(p.name||'')}" placeholder="Ej. Agua natural" required></label><label>Marca<input name="brand" value="${escapeHtml(p.brand||'')}" placeholder="Ej. Bonafont"></label><label>Presentación / detalle<input name="detail" value="${escapeHtml(p.detail||'')}" placeholder="Ej. Botella · 1 L"></label><label>Categoría<input name="category" value="${escapeHtml(p.category||'Abarrotes')}" placeholder="Bebidas, botanas, cremería" required></label><label>Código de barras<input name="code" value="${escapeHtml(p.code||'')}" placeholder="Opcional"></label><label>Imagen<select name="image">${[['soda','Refresco'],['water','Botella de agua'],['milk','Leche'],['cheese','Queso'],['turkey-leg','Jamón de pavo'],['eggs','Huevo'],['chips','Botanas']].map(([id,label])=>`<option value="${id}" ${(p.image||'chips')===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Se vende por<select name="unit">${['pieza','paquete','kg','gramo','docena'].map(u=>`<option ${p.unit===u?'selected':''}>${u}</option>`).join('')}</select></label><label>Contenido neto<input name="content" value="${escapeHtml(p.content||'')}" placeholder="Ej. 600 ml, 200 g"></label><label>Costo de compra ($)<input name="cost" type="number" min="0" step="0.01" value="${p.cost||0}" required></label><label>Precio de venta ($)<input name="price" type="number" min="0.01" step="0.01" value="${p.price||''}" required></label>${editing?'':`<label>Existencia inicial<input name="stock" type="number" min="0" step="0.001" value="0"></label><label>Proveedor (opcional)<input name="supplier" placeholder="Nombre del proveedor"></label>`}<label>Aviso de pocas existencias<input name="minimum" type="number" min="0" step="0.001" value="${p.minimum||0}"></label><label>Caducidad (opcional)<input name="expiry" type="date" value="${p.expiry||''}"></label></div><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn">${editing?'Guardar cambios':'Crear producto'}</button></div></form></div>`;}
function reinvestmentPage(){return `<section class="summary reinvestment-home"><span class="eyebrow">COMPRAS Y EXISTENCIAS</span><h2>Reinversión</h2><p class="settings-intro">¿Qué necesitas hacer hoy?</p><div class="reinvestment-actions"><button class="reinvestment-choice" data-action="choose-restock"><span class="choice-icon">↻</span><span><b>Resurtir producto</b><small>Agrega mercancía a una ficha existente.</small></span><strong>→</strong></button><button class="reinvestment-choice" data-action="new-product"><span class="choice-icon">＋</span><span><b>Producto nuevo</b><small>Crea su ficha y registra la cantidad inicial.</small></span><strong>→</strong></button></div></section>`;}
function restockSelectionPage(){const query=state.restockQuery.toLowerCase();const products=state.products.filter(p=>`${p.name} ${p.brand||''} ${p.detail||''} ${p.code||''}`.toLowerCase().includes(query));return `<section class="summary restock-selection"><button class="text-button back-link" data-action="back-reinvestment">← Volver a Reinversión</button><span class="eyebrow">INVENTARIO</span><h2>Resurtir producto</h2><p class="settings-intro">Busca y elige el producto que llegó. Se sumará a la existencia actual.</p><div class="search-wrap restock-search"><span>⌕</span><input id="restock-search" value="${escapeHtml(state.restockQuery)}" placeholder="Nombre, marca o código de barras" autocomplete="off"></div><div class="restock-list">${products.map(p=>`<article class="restock-card"><img src="./assets/products/${imageFor(p)}.svg" alt=""><div class="restock-info"><span class="eyebrow">${escapeHtml(p.category)}</span><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml([p.brand,p.detail,p.content].filter(Boolean).join(' · '))}</p><div class="restock-stats"><span>Existencia <b>${p.stock} ${escapeHtml(p.unit)}</b></span><span>Vendidas desde compra <b>${Number(p.soldSinceRestock||0)} ${escapeHtml(p.unit)}</b></span><span>Costo actual <b>${money(p.cost)} / ${escapeHtml(p.unit)}</b></span></div></div><div class="restock-actions"><button class="primary-btn" data-purchase="${p.id}">Elegir y resurtir</button></div></article>`).join('')||'<p class="muted">No hay productos que coincidan con la búsqueda.</p>'}</div></section>`;}
function updateCashCount(event){const form=document.querySelector('#dialog-form');if(!form)return;const fields=[...form.querySelectorAll('[data-denomination]')],totalInput=form.querySelector('[name="counted"]'),preview=document.querySelector('#cash-count-total');if(event?.target===totalInput)fields.forEach(input=>input.value='');const hasCounts=fields.some(input=>input.value!==''),sum=fields.reduce((total,input)=>total+Number(input.dataset.denomination)*Math.max(0,Number(input.value)||0),0);if(hasCounts)totalInput.value=sum.toFixed(2);if(preview)preview.textContent=money(hasCounts?sum:Number(totalInput.value||0));}function closeCashDialog(){const d=state.dialog;return `<div class="modal-backdrop" data-action="close-dialog"><section class="form-modal close-report"><button class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">CIERRE DE TURNO · ${escapeHtml(d.session.operator||'')}</span><h2>Resumen de caja</h2><p class="report-period">${new Date(d.session.openedAt).toLocaleString('es-MX')} — ${new Date().toLocaleString('es-MX')}</p><div class="report-totals"><div><span>Ventas en efectivo</span><b>${money(d.cashSales)}</b></div><div><span>Tarjeta y transferencia</span><b>${money(d.nonCash)}</b></div><div><span>Entradas de caja</span><b>${money(d.cashIn)}</b></div><div><span>Salidas de caja</span><b>− ${money(d.cashOut)}</b></div><div class="report-expected"><span>Fondo inicial + efectivo neto</span><b>${money(d.expected)}</b></div></div><h3>Salidas de efectivo · ${(d.cashOutRows||[]).length} movimientos</h3><div class="report-products">${(d.cashOutRows||[]).map(x=>`<div><span>${x.reason==='proveedor'?'Pago a proveedor':x.reason==='resguardo'?'Retiro para guardar o depositar':'Otro retiro'}${x.note?` · ${escapeHtml(x.note)}`:''}<small>${new Date(x.date).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})}</small></span><b>− ${money(x.amount)}</b></div>`).join('')||'<p class="muted">No hubo retiros ni pagos de caja.</p>'}</div><h3>Productos vendidos · ${d.productRows.length} productos distintos</h3><div class="report-products">${d.productRows.map(p=>`<div><span>${escapeHtml(p.name)} <small>× ${p.quantity} ${escapeHtml(p.unit||'pieza')}</small></span><b>${money(p.total)}</b></div>`).join('')||'<p class="muted">No se registraron ventas en este turno.</p>'}</div><h3>Ventas del turno · ${d.sales.length} tickets</h3><div class="report-tickets">${d.sales.map(s=>`<article><header><b>${new Date(s.date).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})} · ${escapeHtml(s.method)}</b><strong>${money(s.total)}</strong></header><p>${s.items.map(i=>`${escapeHtml(i.name)} × ${i.qty} ${escapeHtml(i.unit||'pieza')}`).join(' · ')}</p></article>`).join('')||'<p class="muted">Sin tickets.</p>'}</div><form id="dialog-form"><h3 class="cash-count-heading">Cuenta el efectivo</h3><p class="cash-count-help">Escribe cuántos billetes y monedas hay. El total se calcula solo.</p><div class="cash-denominations">${[[1000,'$1,000'],[500,'$500'],[200,'$200'],[100,'$100'],[50,'$50'],[20,'$20'],[10,'$10'],[5,'$5'],[2,'$2'],[1,'$1'],[0.5,'$0.50']].map(([value,label])=>`<label>${label}<input data-denomination="${value}" type="number" min="0" step="1" inputmode="numeric" placeholder="0"></label>`).join('')}</div><div class="cash-count-preview"><span>Total contado en cajón</span><b id="cash-count-total">$0.00</b></div><label>O escribe el total manualmente ($)<input name="counted" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Escribe el total contado" required></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Volver</button><button class="primary-btn">Confirmar corte y cerrar caja</button></div></form></section></div>`;}function settingsPage(){return `<section class="settings-page"><span class="eyebrow">PREFERENCIAS DEL NEGOCIO</span><h2>Cuida y administra tu tienda</h2><p class="settings-intro">Datos, copias de seguridad y acceso del personal.</p><article class="setting-card storage-status-card"><div class="setting-icon">▣</div><div class="setting-copy"><h3>Guardado en este teléfono</h3><p>Las ventas se guardan primero en el almacenamiento local de esta aplicación; no necesitas tener una carpeta conectada para abrir caja.</p><small>${state.storagePersisted===true?'Chrome protege estos datos contra la limpieza automática.':state.storagePersisted===false?'Chrome no confirmó protección contra limpieza automática; descarga respaldos con frecuencia.':'Estado de almacenamiento no disponible.'}${state.storageUsage!==null?' · Uso aproximado: '+formatBytes(state.storageUsage)+(state.storageQuota?' de '+formatBytes(state.storageQuota):''):''}</small></div></article><article class="setting-card"><div class="setting-icon">▱</div><div class="setting-copy"><h3>Carpeta de datos</h3><p>${state.folder?(state.folderAccess==='granted'?'La carpeta está activa y recibe los guardados. Se conserva una copia local temporal por si Chrome retira el permiso.':'La carpeta y su vínculo siguen guardados. Chrome retiró temporalmente el permiso; pulsa Reconectar carpeta para continuar sin volver a buscarla.'):'Elige dónde guardar tus datos. La información también se conserva en este dispositivo.'}</p></div><button class="primary-btn" data-action="folder">${state.folder?(state.folderAccess==='granted'?'Cambiar carpeta':'Reconectar carpeta'):'Elegir carpeta'}</button></article><article class="setting-card"><div class="setting-icon">↓</div><div class="setting-copy"><h3>Respaldo de la tienda</h3><p>Descarga un archivo para guardar tus productos, ventas y cortes. Puedes cargarlo para recuperar la información.</p></div><div class="setting-buttons"><button class="secondary-btn" data-action="backup">Descargar respaldo</button><button class="secondary-btn" data-action="restore">Restaurar respaldo</button></div></article><article class="setting-card"><div class="setting-icon">◷</div><div class="setting-copy"><h3>Historial de ventas</h3><p>Detalle guardado: ${state.sales.length} ventas · Resúmenes conservados: ${state.archives.length} meses.</p><small>Antes de eliminar detalle antiguo, se guardará un respaldo y se conservarán los totales por mes.</small></div><button class="secondary-btn" data-action="archive">Archivar detalle mayor a un año</button></article><article class="setting-card"><div class="setting-icon">⌑</div><div class="setting-copy"><h3>Contraseña de acceso</h3><p>PIN de demostración inicial: 1234. Cámbialo para este dispositivo.</p></div><button class="secondary-btn" data-action="change-pin">Cambiar contraseña</button></article><article class="setting-card"><div class="setting-icon">↪</div><div class="setting-copy"><h3>Turno actual</h3><p>Sesión: ${escapeHtml(state.operator||'Sin operador')}</p></div><button class="secondary-btn" data-action="logout">Cerrar sesión</button></article></section>`;}function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function render(){document.querySelector('#app').innerHTML=state.operator?layout():loginPage();bind();}
function bind(){document.querySelectorAll('[data-cart-indicator]').forEach(e=>{const row=state.cart.find(i=>i.id===e.dataset.cartIndicator),card=e.closest('.product-card');e.hidden=!row;card?.classList.toggle('in-cart',!!row);if(row)e.textContent='✓ '+Number(row.qty.toFixed(3))+' '+row.unit;});document.querySelector('[data-action="view-cart"]')?.addEventListener('click',()=>document.querySelector('.ticket')?.scrollIntoView({behavior:'smooth',block:'start'}));document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{stopCamera();state.view=e.dataset.view;render();});document.querySelectorAll('[data-cat]').forEach(e=>e.onclick=()=>{state.category=e.dataset.cat;render();});document.querySelectorAll('[data-add]').forEach(e=>e.onclick=()=>{const p=state.products.find(p=>p.id===e.dataset.add),origin=captureCartOrigin(e);if(p.unit==='docena'){state.addOrigin=origin;state.portionProduct=p;state.portionAmount='';render();document.querySelector('#egg-amount')?.focus();}else if(p.unit==='kg'||p.unit==='gramo'){state.addOrigin=origin;state.weightProduct=p;state.weightUnit='g';state.weightAmount='';render();document.querySelector('#weight-amount')?.focus();}else{animateCartFly(origin);add(p);}});document.querySelectorAll('[data-edit]').forEach(e=>e.onclick=()=>openProductForm(state.products.find(p=>p.id===e.dataset.edit)));document.querySelectorAll('[data-delete-product]').forEach(e=>e.onclick=()=>openProductDelete(state.products.find(p=>p.id===e.dataset.deleteProduct)));document.querySelector('[data-action="confirm-delete-product"]')?.addEventListener('click',confirmProductDelete);document.querySelectorAll('[data-inventory-filter]').forEach(e=>e.onclick=()=>{state.inventoryFilter=e.dataset.inventoryFilter;render();});document.querySelectorAll('[data-purchase]').forEach(e=>e.onclick=()=>openMovement('purchase',state.products.find(p=>p.id===e.dataset.purchase)));document.querySelectorAll('[data-count]').forEach(e=>e.onclick=()=>openMovement('count',state.products.find(p=>p.id===e.dataset.count)));document.querySelectorAll('[data-qty]').forEach(e=>e.onclick=()=>{const r=state.cart.find(i=>i.id===e.dataset.qty);r.qty=Math.max(.001,Math.round((r.qty+Number(e.dataset.delta))*1000)/1000);render();});document.querySelectorAll('[data-inputqty]').forEach(e=>e.onchange=()=>{const r=state.cart.find(i=>i.id===e.dataset.inputqty);r.qty=Math.max(.001,Number(e.value)||1);render();});document.querySelector('#search')?.addEventListener('input',e=>{const cursor=e.target.selectionStart;state.query=e.target.value;const p=state.products.find(p=>p.code&&p.code===state.query.trim());render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(cursor,cursor);if(p){add(p);state.query='';render();}});document.querySelector('#restock-search')?.addEventListener('input',e=>{const cursor=e.target.selectionStart;state.restockQuery=e.target.value;render();const input=document.querySelector('#restock-search');input?.focus();input?.setSelectionRange(cursor,cursor);});document.querySelector('#login-form')?.addEventListener('submit',e=>{e.preventDefault();login();});document.querySelectorAll('[data-denomination]').forEach(input=>input.addEventListener('input',updateCashCount));document.querySelector('[name="counted"]')?.addEventListener('input',updateCashCount);document.querySelector('#dialog-form')?.addEventListener('submit',e=>{e.preventDefault();if(state.dialog.type==='close-summary')completeCashClose(e.currentTarget);else if(state.dialog.type==='product-new'||state.dialog.type==='product-edit')saveProduct(e.currentTarget);else if(state.dialog.type==='purchase'||state.dialog.type==='count')saveMovement(e.currentTarget);else if(state.dialog.type==='pin')changePin(e.currentTarget);else if(state.dialog.type==='payment')completePayment(e.currentTarget);else if(state.dialog.type==='cash-out')completeCashOut(e.currentTarget);});document.querySelector('[data-action="folder"]')?.addEventListener('click',chooseFolder);document.querySelector('[data-action="charge"]')?.addEventListener('click',checkout);document.querySelector('[data-action="clear"]')?.addEventListener('click',()=>{state.cart=[];render();});document.querySelector('[data-action="new-product"]')?.addEventListener('click',()=>openProductForm());document.querySelector('[data-action="choose-restock"]')?.addEventListener('click',()=>{state.view='resurtir';state.restockQuery='';render();});document.querySelector('[data-action="back-reinvestment"]')?.addEventListener('click',()=>{state.view='reinversion';state.restockQuery='';render();});document.querySelector('[data-action="camera"]')?.addEventListener('click',startCamera);document.querySelector('[data-action="stop-camera"]')?.addEventListener('click',()=>{stopCamera();render();});document.querySelectorAll('[data-action="cash"]').forEach(e=>e.onclick=()=>isOpen()?closeCash():openCash());document.querySelector('[data-action="close-cash"]')?.addEventListener('click',closeCash);document.querySelector('[data-action="cash-out"]')?.addEventListener('click',()=>cashMovement('out'));document.querySelectorAll('[data-action="backup"]').forEach(e=>e.onclick=backup);document.querySelectorAll('[data-action="restore"]').forEach(e=>e.onclick=restore);document.querySelectorAll('[data-action="archive"]').forEach(e=>e.onclick=archiveOldSales);document.querySelector('[data-action="change-pin"]')?.addEventListener('click',()=>{state.dialog={type:'pin'};render();});document.querySelector('[data-action="logout"]')?.addEventListener('click',logout);document.querySelectorAll('[data-action="cancel-dialog"]').forEach(e=>e.onclick=()=>{if(state.dialog?.deleting)return;state.dialog=null;render();});document.querySelector('[data-action="close-dialog"]')?.addEventListener('click',e=>{if(e.target===e.currentTarget&&!state.dialog?.deleting){state.dialog=null;render();}});document.querySelector('[data-action="cancel-egg"]')?.addEventListener('click',()=>{state.addOrigin=null;state.portionProduct=null;state.portionAmount='';render();});document.querySelector('[data-action="dismiss-egg"]')?.addEventListener('click',e=>{if(e.target===e.currentTarget){state.addOrigin=null;state.portionProduct=null;state.portionAmount='';render();}});document.querySelectorAll('[data-egg-quick]').forEach(e=>e.onclick=()=>{state.portionAmount=e.dataset.eggQuick;render();document.querySelector('#egg-amount')?.focus();});const eggInput=document.querySelector('#egg-amount');eggInput?.addEventListener('input',()=>{state.portionAmount=eggInput.value;const amount=Number(eggInput.value),valid=Number.isInteger(amount)&&amount>0,preview=document.querySelector('#egg-preview'),button=document.querySelector('[data-action="confirm-egg"]');preview.textContent=valid?'Total: '+money(state.portionProduct.price*amount/12):'Elige una cantidad para calcular el total';button.disabled=!valid;});document.querySelector('[data-action="confirm-egg"]')?.addEventListener('click',()=>{const amount=Number(document.querySelector('#egg-amount').value),product=state.portionProduct;if(Number.isInteger(amount)&&amount>0&&product){const origin=state.addOrigin;state.addOrigin=null;state.portionProduct=null;state.portionAmount='';animateCartFly(origin);add(product,amount);}});document.querySelector('[data-action="cancel-weight"]')?.addEventListener('click',()=>{state.addOrigin=null;state.weightProduct=null;render();});document.querySelector('[data-action="dismiss-weight"]')?.addEventListener('click',e=>{if(e.target===e.currentTarget){state.addOrigin=null;state.weightProduct=null;render();}});document.querySelectorAll('[data-weight-unit]').forEach(e=>e.onclick=()=>{const input=document.querySelector('#weight-amount'),oldUnit=state.weightUnit,newUnit=e.dataset.weightUnit,current=Number(state.weightAmount||input?.value||0);if(current>0&&oldUnit!==newUnit)state.weightAmount=String(oldUnit==='g'?current/1000:current*1000);state.weightUnit=newUnit;render();document.querySelector('#weight-amount')?.focus();});const weightInput=document.querySelector('#weight-amount');weightInput?.addEventListener('input',()=>{state.weightAmount=weightInput.value;const amount=Number(weightInput.value),kg=state.weightUnit==='g'?amount/1000:amount,preview=document.querySelector('#weight-preview'),button=document.querySelector('[data-action="confirm-weight"]');if(amount>0){preview.textContent='Total: '+money((state.weightProduct.unit==='gramo'?state.weightProduct.price*1000:state.weightProduct.price)*kg);button.disabled=false;}else{preview.textContent='Escribe la cantidad para calcular el total';button.disabled=true;}});document.querySelector('[data-action="confirm-weight"]')?.addEventListener('click',()=>{const amount=Number(document.querySelector('#weight-amount').value),kg=state.weightUnit==='g'?amount/1000:amount,product=state.weightProduct;if(amount>0&&product){const origin=state.addOrigin;state.addOrigin=null;state.weightProduct=null;state.weightAmount='';animateCartFly(origin);add(product,kg);}});document.querySelectorAll('[data-payment-method]').forEach(e=>e.onclick=()=>{state.dialog.method=e.dataset.paymentMethod;render();});const paymentInput=document.querySelector('#payment-received');paymentInput?.addEventListener('input',()=>{state.dialog.paid=paymentInput.value;const paid=Number(paymentInput.value),total=state.dialog.total,change=document.querySelector('#payment-change'),button=document.querySelector('#dialog-form .primary-btn');change.textContent=money(Math.max(0,paid-total));button.disabled=paid<total;});}async function start(){await openDb();await inspectStorage();const snapshot=await getSetting('snapshot');if(snapshot)applyData(snapshot);state.folder=await getHandle();if(state.folder){try{state.folderAccess=await state.folder.queryPermission({mode:'readwrite'});if(state.folderAccess==='granted'){if(!await loadFile()&&state.dataLoaded)await persist();}else state.folderSyncPending=true;}catch{state.folderAccess='prompt';state.folderSyncPending=true;}}else state.folderSyncPending=false;state.pinHash=await getSetting('pinHash');if(!state.pinHash){state.pinHash=await pinDigest('1234');await putSetting('pinHash',state.pinHash);}const session=state.cash.find(c=>c.status==='open');if(session)state.operator=session.operator||(session.logins||[]).at(-1)?.name||'Operador';render();if('serviceWorker'in navigator&&location.protocol!=='file:'){try{const registration=await navigator.serviceWorker.register('./sw.js');registration.update().catch(()=>{});if(registration.waiting)registration.waiting.postMessage({type:'SKIP_WAITING'});let refreshed=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshed){refreshed=true;location.reload();}});}catch{}}}
start();
